// Workspace settings: the MongoDB data destinations and the checkpoint switch. Only admins can change them.
// Every connection and schedule writes to the default destination. A connection string carries the credentials and the target database; the last connection test is kept with it.
// Incremental extraction reads from a checkpoint, so it is available only while checkpoints are enabled.
function defaultSettings(updatedAt=Date.now()){const destination=(id,name,uri,tested)=>({id,name,type:'mongo',uri,test:tested?{status:'ok',uri,at:updatedAt}:null,updatedAt,updatedBy:'jordan@aziro.com'});return {checkpoint:{enabled:true},defaultDestination:'d-analytics',destinations:[destination('d-analytics','Analytics database','mongodb://edap_writer:demo-Pa55w0rd@edap-mongo.aziro.internal:27017/edap_analytics',true),destination('d-archive','Archive cluster','mongodb+srv://edap_archive:demo-Arch1ve@archive.aziro-data.mongodb.net/edap_archive?retryWrites=true',false)]};}
