let overviewRange='7d';
const overviewRanges={'24h':{label:'Last 24 hours',duration:86400000,buckets:6},'7d':{label:'Last 7 days',duration:604800000,buckets:7},'30d':{label:'Last 30 days',duration:2592000000,buckets:10}};
