const bucketLabel=(time,key)=>new Date(time).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',...(key==='24h'?{hour:'2-digit',minute:'2-digit'}:{month:'short',day:'numeric'})});
const ACTIVITY_COLORS=['#2B50A3','#E85D04','#1BA87C','#C98500','#834E9F','#D93650'],ACTIVITY_OTHER='#8A94A3';
const activitySlots=()=>new Map([...new Set([...state.connections.map(c=>c.app),...state.runs.map(r=>r.app)])].map((id,i)=>[id,ACTIVITY_COLORS[i]||ACTIVITY_OTHER]));
function activityData(now=Date.now()){
 const range=overviewRanges[activityRange],start=now-range.duration,slots=activitySlots();
 const apps=[...slots.keys()].map(meta).filter(Boolean).sort((a,b)=>a.name.localeCompare(b.name));
 const app=apps.find(a=>a.id===activityApp)||null;
 const completed=state.runs.filter(r=>r.status==='completed'&&r.time>=start&&r.time<=now&&(!app||r.app===app.id));
 const series=[...slots.keys()].map(id=>{const rs=completed.filter(r=>r.app===id);return {id,name:meta(id)?.name||id,color:slots.get(id),total:rs.reduce((n,r)=>n+r.count,0),runs:rs.length};}).filter(x=>x.runs);
 const buckets=Array.from({length:range.buckets},(_,i)=>{
  const from=start+i*range.duration/range.buckets,to=start+(i+1)*range.duration/range.buckets;
  const inBucket=completed.filter(r=>r.time>=from&&(i===range.buckets-1?r.time<=to:r.time<to));
  const segments=series.map(x=>{const rs=inBucket.filter(r=>r.app===x.id);return {id:x.id,name:x.name,color:x.color,count:rs.reduce((n,r)=>n+r.count,0),runs:rs.length};}).filter(x=>x.runs);
  return {label:bucketLabel(to,activityRange),count:segments.reduce((n,x)=>n+x.count,0),runs:segments.reduce((n,x)=>n+x.runs,0),segments};
 });
 return {range,apps,app,series,buckets,total:completed.reduce((n,r)=>n+r.count,0)};
}
const plural=(n,word)=>n+' '+word+(n===1?'':'s');
function niceScale(max){if(!(max>0))return {step:1,max:1};const raw=max/4,base=10**Math.floor(Math.log10(raw));const step=[1,2,2.5,3,5,10].map(m=>m*base).find(m=>raw<=m);return {step,max:Math.ceil(max/step)*step};}
const compact=n=>n>=1000?(n/1000).toLocaleString('en-IN',{maximumFractionDigits:1})+'K':String(n);
function activityChart(a){
 const scale=niceScale(Math.max(...a.buckets.map(b=>b.count))),max=scale.max;
 const ticks=[];for(let v=scale.step;v<=max;v+=scale.step)ticks.push(v);
 const grid=ticks.map(v=>`<i class="chart-grid" style="bottom:${(v/max*100).toFixed(3)}%"></i><em class="chart-tick" style="bottom:${(v/max*100).toFixed(3)}%">${compact(v)}</em>`).join('');
 const cols=a.buckets.map(b=>`<div class="chart-col${b.runs?' has-data':''}" data-label="${esc(b.label)}" data-count="${b.count}" data-runs="${b.runs}"><div class="chart-stack" style="height:${b.count/max*100}%">${b.count?`<b>${fmt(b.count)}</b>`:''}${b.segments.map(x=>`<button type="button" class="chart-seg" style="--seg:${x.color};--grow:${x.count}" data-name="${esc(x.name)}" data-count="${x.count}" data-runs="${x.runs}" aria-label="${esc(x.name)}: ${fmt(x.count)} records in ${plural(x.runs,'run')} on ${esc(b.label)}"></button>`).join('')}</div><span>${b.label}</span></div>`).join('');
 const legend=a.app?`<div class="chart-legend"><button type="button" class="text-button" data-action="activity-app" data-id="all">← All connectors</button></div>`:`<ul class="chart-legend">${a.series.map(x=>`<li><button type="button" class="legend-item" data-action="activity-app" data-id="${x.id}" style="--seg:${x.color}" title="Show only ${esc(x.name)}"><span class="legend-swatch"></span><img src="assets/logos/${x.id}.svg" alt="" width="14" height="14" decoding="async">${esc(x.name)}<b>${fmt(x.total)}</b></button></li>`).join('')}</ul>`;
 return `<div class="chart-scroll"><div class="chart activity-chart stacked" role="group" aria-label="Records extracted per ${activityRange==='24h'?'period':'day'}, split by connector"><div class="chart-plot">${grid}${cols}</div></div></div>${legend}<div class="chart-tip" hidden></div>`;
}
function overviewData(now=Date.now()) {
 const range=overviewRanges[overviewRange], start=now-range.duration;
 const runs=state.runs.filter(r=>r.time>=start&&r.time<=now);
 const completed=runs.filter(r=>r.status==='completed');
 const settled=runs.filter(r=>['completed','failed'].includes(r.status));
 const sources=state.connections.map(c=>{
  const history=state.runs.filter(r=>r.connection===c.id).sort((a,b)=>b.time-a.time);
  const last=history.find(r=>r.status==='completed');
  const latest=history.find(r=>['completed','failed'].includes(r.status));
  const running=history.some(r=>r.status==='running');
  const schedules=state.schedules.filter(s=>s.connection===c.id&&s.active);
  const threshold=schedules.length?Math.min(...schedules.map(s=>intervalFor(s.frequency))):86400000;
  const stale=!!last&&now-last.time>threshold;
  const freshness=!last?'Not extracted':stale?'Stale':'Current';
  let issue=null;
  if(c.status==='attention')issue={title:'Authorization expired',description:'Reconnect your account to resume extraction.',action:'reauth',id:c.id,label:'Reconnect',admin:true};
  else if(!running&&latest?.status==='failed')issue={title:'Extraction failed',description:latest.error||'Review the last run and retry the extraction.',action:'run-detail',id:latest.id,label:'View failed run'};
  else if(schedules.some(s=>s.next<now))issue={title:'Schedule overdue',description:'A scheduled extraction is past its next run time.',href:'#schedules',label:'View schedule'};
  else if(!running&&stale)issue={title:'Refresh needed',description:'Run an extraction to bring this data up to date.',action:'run',id:c.id,label:'Run extraction'};
  else if(!running&&!last)issue={title:'First extraction pending',description:'Run an extraction to make data available.',action:'run',id:c.id,label:'Run extraction'};
  return {c,last,threshold,freshness,running,issue};
 });
 const buckets=Array.from({length:range.buckets},(_,i)=>{
  const from=start+i*range.duration/range.buckets,to=start+(i+1)*range.duration/range.buckets;
  return {label:new Date(to).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',...(overviewRange==='24h'?{hour:'2-digit',minute:'2-digit'}:{month:'short',day:'numeric'})}),count:completed.filter(r=>r.time>=from&&(i===range.buckets-1?r.time<=to:r.time<to)).reduce((n,r)=>n+r.count,0)};
 });
 return {range,runs,completed,settled,sources,buckets,total:completed.reduce((n,r)=>n+r.count,0),issues:sources.filter(s=>s.issue)};
}
const ago=(time,now=Date.now())=>{const m=Math.max(0,Math.floor((now-time)/60000));if(m<1)return 'just now';if(m<60)return m+' min ago';const h=Math.floor(m/60);if(h<24)return h+(h===1?' hour':' hours')+' ago';const d=Math.floor(h/24);return d+(d===1?' day':' days')+' ago';};
function overviewStats(){
 const connected=state.connections.filter(c=>c.status==='connected').length,attention=state.connections.filter(c=>c.status==='attention').length;
 const completed=state.runs.filter(r=>r.status==='completed'),failed=state.runs.filter(r=>r.status==='failed'),running=state.runs.filter(r=>r.status==='running').length,cancelled=state.runs.filter(r=>r.status==='cancelled').length;
 return {total:state.connections.length,connected,attention,runs:state.runs.length,completed:completed.length,running,cancelled,successRate:state.runs.length?Math.round(completed.length/state.runs.length*100):null,failed:failed.length,lastFailure:failed.length?Math.max(...failed.map(r=>r.time)):null,records:completed.reduce((n,r)=>n+r.count,0),contributors:new Set(completed.map(r=>r.connection)).size};
}
function statTiles(){
 if(!state.connections.length&&!state.runs.length)return '';
 const s=overviewStats();
 // Each tile is a link to the page behind its number. Only the failure tile changes tone, and only when failures exist.
 const tile=t=>`<a class="metric${t.crit?' is-crit':''}" href="${t.href}"><div class="metric-body"><span class="metric-icon">${ico(t.icon)}</span><div class="metric-label">${t.label}</div><div class="metric-value">${t.value}</div>${t.sub}</div><div class="metric-foot">${t.action} ${ico('arrow')}</div></a>`;
 return `<div class="metrics overview-stats">${[
  {label:'Connected connectors',icon:'connections',href:'#connections',action:'View connections',value:`${fmt(s.connected)}<span class="metric-of">of ${fmt(s.total)}</span>`,sub:s.attention?`<span class="metric-flag">${ico('alert')}${s.attention} need${s.attention===1?'s':''} attention</span>`:'<small>All connections healthy</small>'},
  {label:'Total extractions',icon:'runs',href:'#runs',action:'View run history',value:fmt(s.runs),sub:`<small>${[s.running&&`${s.running} running`,s.cancelled&&`${s.cancelled} cancelled`].filter(Boolean).join(' · ')||'All time'}</small>`},
  {label:'Successful extractions',icon:'check',href:'#runs/completed',action:'View successful runs',value:fmt(s.completed),sub:`<small>${s.successRate===null?'No extractions yet':s.successRate+'% of extractions'}</small>`},
  {label:'Failed extractions',icon:s.failed?'fail':'shield',crit:s.failed>0,href:s.failed?'#runs/failed':'#runs',action:s.failed?`Review failure${s.failed===1?'':'s'}`:'View run history',value:fmt(s.failed),sub:`<small>${s.lastFailure?'Last failure '+ago(s.lastFailure):'No failures recorded'}</small>`},
  {label:'Records extracted',icon:'database',href:'#runs/completed',action:'View completed runs',value:fmt(s.records),sub:`<small>Across ${s.contributors} connector${s.contributors===1?'':'s'}</small>`}
 ].map(tile).join('')}</div>`;
}
function overview(){
 const d=overviewData(),a=activityData();
 const issueAction=i=>i.href?`<a class="btn small" href="${i.href}">${i.label} →</a>`:`<button class="btn small" data-action="${i.action}" data-id="${i.id}" ${i.admin?disabled():''}>${i.label} →</button>`;
 return title('Overview','Track your connections and extraction activity.',`<div class="actions"><a class="btn primary" href="#catalog">${ico('plus')} Add connection</a></div>`)+
 (!state.connections.length?`<section class="welcome"><div><div class="eyebrow">START WITH YOUR FIRST SOURCE</div><h2>Connect your tools. Bring your data together.</h2><p>Add a personal account, choose your data, and run your first extraction.</p></div><a class="btn" href="#catalog">Explore connectors ${ico('arrow')}</a></section>`:'')+statTiles()+
 `<div class="overview-top-grid"><section class="panel attention-panel"><div class="panel-head"><div><h2>${d.issues.length?'Needs attention':'No issues to show'} <span class="pill-count">${d.issues.length}</span></h2><p>Current issues across your connections.</p></div><span class="badge ${d.issues.length?'attention':'connected'}">${d.issues.length?'Action needed':'All clear'}</span></div>${d.issues.map(({c,issue})=>`<div class="attention-row">${appIcon(meta(c.app))}<div class="attention-copy"><strong>${esc(c.name)} <span>· ${issue.title}</span></strong><p>${esc(issue.description)}</p></div>${issueAction(issue)}</div>`).join('')}${d.issues.some(s=>s.issue.admin)&&!canEdit()?'<p class="attention-note">Ask an admin to reconnect expired accounts. Viewers can run and retry extractions.</p>':''}${!d.issues.length?`<div class="attention-note">${state.connections.length?'No unresolved failures or overdue data refreshes.':'Add a connection to begin monitoring its health and data freshness.'}</div>`:''}</section>
 <section class="panel overview-activity"><div class="panel-head activity-head"><div><h2>Extraction activity</h2><p>${fmt(a.total)} records extracted · ${a.range.label} · ${a.app?esc(a.app.name):'All connectors'}</p></div><div class="activity-filters"><label class="range-control" for="activity-range">Period<select id="activity-range">${Object.entries(overviewRanges).map(([v,r])=>`<option value="${v}" ${v===activityRange?'selected':''}>${r.label}</option>`).join('')}</select></label><label class="range-control" for="activity-connector">Connector<select id="activity-connector"><option value="all">All connectors</option>${a.apps.map(x=>`<option value="${x.id}" ${a.app?.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label></div></div>${a.total?activityChart(a):'<div class="empty compact-empty"><h3>No completed records for this selection</h3><p>Choose a wider period or another connector, or run an extraction.</p></div>'}</section></div>
 <section class="panel"><div class="panel-head"><div><h2>Data freshness</h2><p>Refresh targets follow your active schedules. Connections without a schedule use a 24-hour target.</p></div><a class="text-button" href="#connections">Manage connections →</a></div>${d.sources.length?`<div class="table-wrap"><table><thead><tr><th>Personal connection</th><th>Connection health</th><th>Last successful run started · IST</th><th>Freshness target</th><th>Data status</th><th></th></tr></thead><tbody>${d.sources.map(({c,last,threshold,freshness,running})=>`<tr><td><a class="table-source" href="#connection/${c.id}">${appIcon(meta(c.app))}<div><strong>${esc(c.name)}</strong><small>${esc(c.account)}</small></div></a></td><td>${badge(c.status)}</td><td>${last?date(last.time):'Never extracted'}</td><td>${threshold===3600000?'1 hour':threshold===604800000?'7 days':'24 hours'}</td><td><span class="badge ${freshness==='Current'?'connected':'attention'}">${freshness}</span>${running?'<small class="refreshing">Refreshing…</small>':''}</td><td><button class="text-button" data-action="${c.status==='attention'?'reauth':'run'}" data-id="${c.id}" ${(c.status==='attention'&&!canEdit())||running?'disabled':''}>${c.status==='attention'?'Reconnect':'Run extraction'} →</button></td></tr>`).join('')}</tbody></table></div>`:empty('No data sources yet','Connect your first application to track freshness.')}</section>
 <section class="panel"><div class="panel-head"><div><h2>Recent extractions</h2><p>${d.range.label} · Includes running and cancelled jobs</p></div><a class="text-button" href="#runs">View all runs →</a></div>${d.runs.length?runTable(d.runs.slice(0,5)):'<div class="empty compact-empty"><h3>No runs in this period</h3><p>Choose another reporting period or start an extraction.</p></div>'}</section>`;
}

function catalogPage(){return title('Connector catalog','Connect the applications your organization runs on.')+viewer()+`<div class="toolbar"><div class="search">${ico('search')}<input id="catalog-search" placeholder="Search connectors…" aria-label="Search connectors" value="${esc(filterText)}"></div><span class="result-count" id="catalog-count" role="status"></span></div><div class="category-tags" role="group" aria-label="Filter by category">${['All categories',...new Set(CATALOG.map(a=>a.category))].map(v=>`<button type="button" class="category-tag" data-action="filter-category" data-id="${v}" aria-pressed="${v===category}">${v==='All categories'?'All':v}</button>`).join('')}</div><div class="catalog" id="catalog-grid"></div>`;}
function catalogResults(){const apps=CATALOG.filter(a=>(a.name+' '+a.description).toLowerCase().includes(filterText.toLowerCase())&&(category==='All categories'||a.category===category));$('#catalog-count').textContent=apps.length+(apps.length===1?' connector':' connectors');$('#catalog-grid').innerHTML=apps.map(a=>{const connected=state.connections.filter(c=>c.app===a.id).length;return `<article class="connector-card"><div class="card-top">${appIcon(a,true)}<span class="category">${a.category}</span></div><h3>${a.name}</h3><p>${a.description}</p><div class="card-bottom"><small>${connected?`${connected} connected account${connected>1?'s':''}`:a.auth.join(' / ')}</small><button class="btn small" data-action="connect" data-id="${a.id}" ${disabled()}>${ico('plus')} Connect</button></div></article>`;}).join('')||empty('No matching connectors','Try another application name or category.');}
function connectionsPage(){return title('My connections','Your accounts, configured for the data you need.',`<a class="btn primary" href="#catalog">${ico('plus')} Add connection</a>`)+viewer()+`<div class="toolbar"><div class="search">${ico('search')}<input id="connection-search" placeholder="Search your connections…" aria-label="Search your connections" value="${esc(filterText)}"></div><select id="connection-status" aria-label="Filter connection status">${['All statuses','Connected','Needs attention'].map(v=>`<option ${v===statusFilter?'selected':''}>${v}</option>`).join('')}</select></div><div class="panel" id="connections-table"></div>`;}
function connectionsResults(){
 const list=state.connections.filter(c=>(c.name+' '+c.account+' '+meta(c.app).name).toLowerCase().includes(filterText.toLowerCase())&&(statusFilter==='All statuses'||c.status===(statusFilter==='Connected'?'connected':'attention')));
 if(!list.length){
  $('#connections-table').innerHTML=state.connections.length
   ?empty('No matching connections','Try another search or clear your filters.',`<button class="btn" data-action="clear-connection-filters">Clear filters</button>`)
   :empty('No connections yet','Connect an application to start extracting data.',`<a class="btn primary" href="#catalog">${ico('plus')} Add connection</a>`);
  return;
 }
 $('#connections-table').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Connection</th><th>Account</th><th>Status</th><th>Objects</th><th>Last successful run<span class="column-subtitle">Started · IST</span></th><th>Actions</th></tr></thead><tbody>${list.map(c=>{
  const last=state.runs.filter(r=>r.connection===c.id&&r.status==='completed').sort((a,b)=>b.time-a.time)[0];
  const running=state.runs.some(r=>r.connection===c.id&&r.status==='running');
  const action=c.status==='attention'
   ?`<button class="btn small" data-action="reauth" data-id="${c.id}" ${disabled()}>Reconnect</button>${!canEdit()?'<small class="connection-action-note">Admin required to reconnect</small>':''}`
   :`<button class="btn small" data-action="run" data-id="${c.id}" ${running?'disabled':''}>${ico('play')}${running?'Extraction running':'Run extraction'}</button>`;
  return `<tr class="connection-clickable-row" data-connection-href="#connection/${esc(c.id)}" tabindex="0" aria-label="View ${esc(c.name)}"><td><a class="table-source" href="#connection/${c.id}">${appIcon(meta(c.app))}<div><strong>${esc(c.name)}</strong><small>${meta(c.app).category}</small></div></a></td><td>${esc(c.account)}</td><td>${badge(c.status)}</td><td>${c.objects.length} ${c.objects.length===1?'object':'objects'} selected</td><td>${last?date(last.time):'No successful runs yet'}</td><td><div class="connection-row-actions">${action}<a class="text-button" href="#connection/${c.id}">View connection →</a></div></td></tr>`;
 }).join('')}</tbody></table></div>`;
}

function objectsMarkup(c,editable=true){return meta(c.app).objects.map(o=>`<div class="object-row"><input type="checkbox" id="object-${o}" data-object="${o}" ${c.objects.includes(o)?'checked':''} ${editable?'':'disabled'}><label for="object-${o}">${o}</label><span>${Object.keys(c.mappings[o]||{}).length} fields</span></div>`).join('');}
function viewerDetail(c){
 const a=meta(c.app);
 const tabs=[['extraction','Extraction'],['history','Run history'],['connection','Connection details'],['data','Data configuration'],['json','Configuration JSON']];
 const readOnlyHead=heading=>`<div class="panel-head"><div><h2>${heading} <span class="view-only-badge">View only</span></h2><p>Settings are managed by an admin.</p></div></div>`;
 const valueRow=(label,value,copy='')=>`<div><dt>${label}</dt><dd><span>${esc(value)}</span>${copy?`<button class="text-button copy-value" data-action="copy-connection-value" data-id="${esc(c.id)}" data-field="${copy}" aria-label="Copy ${label.toLowerCase()}">Copy</button>`:''}</dd></div>`;
 const expired=c.status==='attention';
 let body='';
 if(tab==='extraction')body=`<section class="panel"><div class="panel-head"><div><h2>Run extraction</h2><p>Choose how to collect your configured data.</p></div></div><div class="panel-body">${expired?'<div class="help-box warning"><strong>Authorization expired</strong><p>Ask an admin to reconnect this account before running an extraction.</p></div>':'<div class="help-box">Runs use the saved data configuration. You can change the options below for this run.</div>'}${runFields(c)}<button class="btn primary" data-action="start-detail-run" data-id="${esc(c.id)}" ${expired?'disabled':''}>${ico('play')} Run extraction</button></div></section>`;
 if(tab==='history')body=`<section class="panel"><div class="panel-head"><h2>Extraction history</h2></div>${runTable(state.runs.filter(r=>r.connection===c.id))}</section>`;
 if(tab==='connection')body=`<section class="panel">${readOnlyHead('Connection details')}<div class="panel-body"><dl class="read-only-values">${valueRow('Connection name',c.name)}${valueRow('Application',a.name)}${valueRow('Account',c.account,'account')}${valueRow('Authentication method',c.auth)}${valueRow(a.category==='Databases'?'Database host':'Application URL',c.endpoint,'endpoint')}<div><dt>Connection status</dt><dd>${badge(c.status)}</dd></div></dl>${expired?'<div class="help-box warning"><strong>Authorization expired</strong><p>Ask an admin to reconnect this account.</p></div>':''}<button class="btn" data-action="test" data-id="${esc(c.id)}">${ico('shield')} Test connection</button></div></section>`;
 if(tab==='data')body=`<section class="panel">${readOnlyHead('Data configuration')}<div class="panel-body"><h3>Selected objects</h3><div class="object-tags">${c.objects.map(o=>`<span>${esc(o)}</span>`).join('')}</div><dl class="read-only-values">${valueRow('Record limit per object',fmt(c.limit))}${valueRow(a.id==='jira'?'JQL filter':'Source filter',c.filter||'All records')}${valueRow('Destination',destinationName(c.destination))}</dl><h3>Field mappings</h3>${c.objects.map(o=>`<section class="read-only-mappings"><h4>${esc(o)}</h4><div class="table-wrap"><table><thead><tr><th>Source field</th><th>Output field</th></tr></thead><tbody>${Object.entries(c.mappings[o]||{}).map(([src,out])=>`<tr><td>${esc(src)}</td><td><span aria-hidden="true" class="mapping-arrow">→</span>${esc(out)}</td></tr>`).join('')}</tbody></table></div></section>`).join('')}</div></section>`;
 if(tab==='json')body=`<section class="panel"><div class="panel-head"><div><h2>Configuration JSON <span class="view-only-badge">View only</span></h2><p>Settings are managed by an admin.</p></div><button class="btn small" data-action="copy-connection-value" data-field="json" data-id="${esc(c.id)}">Copy JSON</button></div><div class="panel-body"><pre class="viewer-json" tabindex="0" aria-label="Saved connector configuration"><code>${esc(JSON.stringify(configJSON(c),null,2))}</code></pre></div></section>`;
 return `<div class="page-heading"><div class="detail-title">${appIcon(a,true)}<div><h1>${esc(c.name)}</h1><p>${a.category} · Personal connection</p></div></div>${badge(c.status)}</div><div class="tabs" aria-label="Connection sections">${tabs.map(([id,label])=>`<button class="${tab===id?'active':''}" data-action="tab" data-id="${id}" aria-pressed="${tab===id}">${label}</button>`).join('')}</div><div class="viewer-detail">${body}</div>`;
}
async function copyConnectionValue(id,field){
 const c=connection(id);if(!c||!['account','endpoint','json'].includes(field))return;
 const value=field==='json'?JSON.stringify(configJSON(c),null,2):c[field];
 try{await navigator.clipboard.writeText(value);toast(field==='json'?'Configuration JSON copied.':'Copied to clipboard.');}
 catch{openModal('copy','Copy '+(field==='json'?'configuration JSON':field==='account'?'account':'source address'),'Select and copy the text below.',`<textarea class="code" id="copy-fallback" readonly aria-label="Text to copy">${esc(value)}</textarea>`,'<button class="btn" data-action="close-modal">Close</button>');$('#copy-fallback').focus();$('#copy-fallback').select();}
}
function detail(){const c=connection(detailId);if(!c)return empty('Connection not found','This connection may have been removed.',`<a class="btn" href="#connections">Back to connections</a>`);if(!canEdit())return viewerDetail(c);if(!draft)draft=structuredClone(c);const a=meta(c.app);let body='';if(tab==='connection')body=`<section class="panel"><div class="panel-head"><div><h2>Connection details</h2><p>Personal account · ${a.name}</p></div>${badge(c.status)}</div><div class="panel-body"><div class="field"><label for="connection-name">Connection name</label><input id="connection-name" value="${esc(draft.name)}" data-draft="name" ${disabled()} maxlength="80"></div><div class="field"><label for="endpoint">${a.category==='Databases'?'Database host':'Application URL'}</label><input id="endpoint" value="${esc(draft.endpoint)}" data-draft="endpoint" ${disabled()}></div><div class="fields-two"><div class="field"><label>Account</label><input aria-label="Connected account" value="${esc(c.account)}" disabled></div><div class="field"><label>Authentication</label><input aria-label="Authentication method" value="${esc(c.auth)}" disabled></div></div><div class="help-box ${c.status==='attention'?'warning':''}"><strong>${c.status==='attention'?'Authorization expired':'Account connected'}</strong><p>${c.status==='attention'?'Reconnect this account to resume extractions.':'Manage your account and extraction settings below.'}</p></div><div class="actions"><button class="btn" data-action="test" data-id="${c.id}">${ico('shield')} Test connection</button><button class="btn" data-action="reauth" data-id="${c.id}" ${disabled()}>Reconnect account</button></div></div></section><div class="actions"><button class="btn primary" data-action="save-config" ${disabled()}>Save changes</button><button class="btn" data-action="reload-config" ${disabled()}>Reload saved</button><button class="btn danger" data-action="disconnect" data-id="${c.id}" ${disabled()}>Disconnect</button><span class="muted" id="dirty-label">${dirty?'Unsaved changes':'All changes saved'}</span></div>`;
if(tab==='data')body=`<section class="panel"><div class="panel-head"><div><h2>Objects & fields</h2><p>Select what to collect from ${a.name}</p></div><button class="text-button" data-action="all-objects" ${disabled()}>Select all</button></div><div class="panel-body">${objectsMarkup(draft,canEdit())}<div class="fields-two" style="margin-top:24px"><div class="field"><label for="record-limit">Record limit per object</label><input id="record-limit" type="number" min="1" max="1000000" value="${draft.limit}" data-draft="limit" ${disabled()}></div><div class="field"><label for="source-filter">${a.id==='jira'?'JQL filter':'Source filter (optional)'}</label><input id="source-filter" placeholder="All records" value="${esc(draft.filter)}" data-draft="filter" ${disabled()}></div></div><div class="section-label">FIELD MAPPINGS</div><div class="field"><label for="mapping-object">Object</label><select id="mapping-object">${draft.objects.map(o=>`<option>${o}</option>`).join('')}</select></div><div id="mapping-table"></div></div></section><div class="actions"><button class="btn primary" data-action="save-config" ${disabled()}>Save configuration</button><button class="btn" data-action="reload-config" ${disabled()}>Reload saved</button><span class="muted" id="dirty-label">${dirty?'Unsaved changes':'All changes saved'}</span></div>`;
if(tab==='json')body=`<section class="panel"><div class="panel-head"><div><h2>Advanced configuration</h2><p>Validated JSON · Credentials are managed separately</p></div></div><div class="panel-body"><div class="field"><label for="json-editor">Connector configuration</label><textarea id="json-editor" class="code" spellcheck="false" ${disabled()}>${esc(jsonDraft??JSON.stringify(configJSON(draft),null,2))}</textarea></div><p class="error" id="json-error" role="alert"></p><div class="actions"><button class="btn primary" data-action="save-json" ${disabled()}>Validate & save</button><button class="btn" data-action="reload-config" ${disabled()}>Reload saved</button><span class="muted" id="dirty-label">${dirty?'Unsaved changes':'All changes saved'}</span></div></div></section>`;
if(tab==='extraction')body=`<section class="panel"><div class="panel-head"><div><h2>Run extraction</h2><p>Available to viewers and admins</p></div>${ico('play')}</div><div class="panel-body"><div class="help-box">Runs use your saved configuration.</div>${runFields(c)}<button class="btn primary" data-action="start-detail-run" data-id="${c.id}">${ico('play')} Run extraction</button></div></section>`;
if(tab==='history')body=`<section class="panel"><div class="panel-head"><h2>Extraction history</h2></div>${runTable(state.runs.filter(r=>r.connection===c.id))}</section>`;
return `<div class="page-heading"><div class="detail-title">${appIcon(a,true)}<div><h1>${esc(c.name)}</h1><p>${a.category} <span style="margin:0 8px">·</span> Personal connection</p></div></div><button class="btn primary" data-action="run" data-id="${c.id}">${ico('play')} Run extraction</button></div>${viewer()}<div class="tabs" aria-label="Connection sections">${[['connection','Connection'],['data','Data & mappings'],['extraction','Extraction'],['history','Run history'],['json','Advanced JSON']].map(([id,label])=>`<button class="${tab===id?'active':''}" data-action="tab" data-id="${id}" aria-pressed="${tab===id}">${label}</button>`).join('')}</div><div class="${tab==='history'?'':'detail-grid'}"><div>${body}</div>${tab==='history'?'':`<aside class="panel detail-summary">${ico('shield')}<h3 style="margin-top:12px">Connection at a glance</h3><p>This account belongs to you. Extraction settings are managed by admins.</p><dl><dt>APPLICATION</dt><dd>${a.name}</dd><dt>DATA SCOPE</dt><dd>${c.objects.length} of ${a.objects.length} objects</dd><dt>DESTINATION</dt><dd>${esc(destinationName(c.destination))}</dd><dt>CREATED</dt><dd>${date(c.created)}</dd><dt>CONFIGURATION</dt><dd>Saved locally in this browser</dd></dl></aside>`}</div>`;}
function configJSON(c){return {connector:c.app,objects:Object.fromEntries(meta(c.app).objects.map(o=>[o,{enabled:c.objects.includes(o),fields:c.mappings[o]||{}}])),options:{filter:c.filter,maxRecords:Number(c.limit)},destination:c.destination};}
function renderMappings(){if(!$('#mapping-table'))return;const o=$('#mapping-object').value;if(!o){$('#mapping-table').innerHTML='<p class="muted">Select at least one object to map fields.</p>';return;}$('#mapping-table').innerHTML=`<div class="table-wrap"><table class="mapping-table"><thead><tr><th>Source field</th><th>Output field</th></tr></thead><tbody>${Object.entries(draft.mappings[o]||{}).map(([src,out])=>`<tr><td>${esc(src)}</td><td><input aria-label="Output field for ${esc(src)}" class="mapping-input" data-mapping="${esc(src)}" value="${esc(out)}" ${disabled()} maxlength="80"></td></tr>`).join('')}</tbody></table></div>`;}
function destinationHelp(id=state.settings.defaultDestination){const db=mongoTarget(destinationById(id)?.uri||'')?.database;return `Records are written to the ${esc(db||'configured')} database in MongoDB.`;}
// Read-only destination line shown to admins wherever a destination used to be picked; viewers don't see it. It only changes on the Settings page.
function destinationSummary(id){if(!canEdit())return '';return `<div class="destination-summary"><div><span>Destination</span><strong>${esc(destinationName(id))}</strong><span class="view-only-badge">View only</span></div><small>${destinationHelp(id)} <button type="button" class="text-button" data-action="open-settings" data-section="destinations">Change in Settings</button></small></div>`;}
// Stand-in for the projects the connected Jira account can read.
const JIRA_PROJECTS=[['ENG','Engineering'],['PLAT','Platform'],['OPS','Operations'],['SEC','Security']];
// Run form, in the order a run is defined: objects, connector scope (Jira: project key, then optional JQL), extraction mode.
// The destination is shown read-only for every role; it changes on the Settings page.
function runFields(c,prefix='run'){
 const objects=`<div class="field"><label for="${prefix}-object">Object</label><select id="${prefix}-object" required aria-required="true"><option value="all" selected>All objects (${c.objects.length})</option>${c.objects.map(o=>`<option value="${esc(o)}">${esc(o)}</option>`).join('')}</select><small>Choose one object, or extract all of them.</small></div>`;
 const scope=c.app==='jira'?`<div class="field"><label for="${prefix}-project">Project key</label><select id="${prefix}-project" required aria-required="true"><option value="">Select a project</option>${JIRA_PROJECTS.map(([k,name])=>`<option value="${k}">${k} · ${name}</option>`).join('')}</select><small>Required. Only this project is extracted.</small></div><div class="field"><label for="${prefix}-jql">JQL filter (optional)</label><input id="${prefix}-jql" value="${esc(c.filter||'')}" placeholder="status != Done AND updated &gt;= -30d" autocomplete="off" spellcheck="false"><small>Narrows the issues extracted from the selected project. Leave blank for all issues.</small></div>`:'';
 const modeOption=(value,label,help,checked)=>`<label class="choice-option"><input type="radio" name="${prefix}-mode" id="${prefix}-mode-${value}" value="${value}"${checked?' checked':''}><span><strong>${label}</strong><small>${help}</small></span></label>`;
 // Incremental extraction needs a checkpoint. Selecting it checks the setting and reports the result in the note below (see modeNote).
 const mode=`<fieldset class="choice-options run-mode"><legend>Extraction mode</legend>${modeOption('full','Full extraction','Extract every record for the selected objects.',true)}${modeOption('incremental','Incremental extraction','Only records changed since the last successful run.',false)}<p class="mode-note" id="${prefix}-mode-note" role="status" data-destination="${c.destination}" hidden></p></fieldset>`;
 return `${objects}${scope}${mode}${destinationSummary(c.destination)}<div class="field" hidden><label for="${prefix}-outcome">Execution scenario</label><select id="${prefix}-outcome"><option value="success">Successful extraction</option><option value="failure">Temporary source failure</option></select></div><p id="${prefix}-error" class="error" role="alert"></p>`;
}
function runsPage(){return title('Extraction runs','Follow every extraction from start to finish.',`<button class="btn primary" data-action="choose-run">${ico('play')} New extraction</button>`)+`<div class="toolbar"><div class="search">${ico('search')}<input id="run-search" aria-label="Search extraction runs" placeholder="Search by connection or run ID…" value="${esc(filterText)}"></div><select id="run-status" aria-label="Filter run status">${['All statuses','Completed','Running','Failed','Cancelled'].map(v=>`<option ${v===statusFilter?'selected':''}>${v}</option>`).join('')}</select><select id="run-connector" aria-label="Filter connector"><option value="all">All connectors</option>${[...activitySlots().keys()].map(meta).filter(Boolean).sort((a,b)=>a.name.localeCompare(b.name)).map(a=>`<option value="${a.id}" ${a.id===runApp?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div><section class="panel" id="runs-table"></section>`;}
function runsResults(){const list=state.runs.filter(r=>(r.name+' '+r.id).toLowerCase().includes(filterText.toLowerCase())&&(statusFilter==='All statuses'||r.status===statusFilter.toLowerCase())&&(runApp==='all'||r.app===runApp));$('#runs-table').innerHTML=runTable(list);}
function schedulesPage(){return title('Schedules','Keep your data up to date with recurring extractions.',`<button class="btn primary" data-action="new-schedule" ${disabled()}>${ico('plus')} Create schedule</button>`)+viewer()+`<div class="help-box">Manage recurring extractions, or use “Run now” to start one immediately.</div><section class="panel">${state.schedules.length?`<div class="table-wrap"><table><thead><tr><th>Connection</th><th>Frequency</th><th>Mode / destination</th><th>Status</th><th>Next run · IST</th><th>Actions</th></tr></thead><tbody>${state.schedules.map(s=>{const c=connection(s.connection);return `<tr><td><div class="table-source">${appIcon(meta(c.app))}<strong>${esc(c.name)}</strong></div></td><td>${s.frequency==='hourly'?'Every hour':s.frequency==='daily'?'Every day':'Every week'}</td><td>${s.mode}<br><small>${esc(destinationName(s.destination))}</small></td><td>${badge(s.active?'active':'paused')}</td><td>${s.active?date(s.next):'—'}</td><td><div class="actions"><button class="btn small" data-action="schedule-run" data-id="${s.id}">Run now</button><button class="text-button" data-action="edit-schedule" data-id="${s.id}" ${disabled()}>Edit</button><button class="text-button" data-action="toggle-schedule" data-id="${s.id}" ${disabled()}>${s.active?'Pause':'Resume'}</button><button class="text-button" data-action="delete-schedule" data-id="${s.id}" ${disabled()}>Delete</button></div></td></tr>`;}).join('')}</tbody></table></div>`:empty('No schedules yet','Choose a connection and set how often its data should be collected.')}</section>`;}
const destinationById=id=>state.settings.destinations.find(d=>d.id===id);
const destinationName=(id=state.settings.defaultDestination)=>destinationById(id)?.name||'Deleted destination';
// Settings has one page per area; #settings lists them. [title, description]
const SETTINGS_SECTIONS={destinations:['Data destinations','Configure where extracted records are stored.'],checkpoints:['Checkpoints','Save a checkpoint after each extraction so incremental extraction fetches only changed records.']};
// The target database is the path of the connection string: mongodb://user:password@host:27017/edap_analytics?authSource=admin
function mongoTarget(uri){const m=/^mongodb(?:\+srv)?:\/\/(?:[^@\/?#]*@)?([^@\/?#]+)(?:\/([^?#]*))?/.exec(String(uri).trim());if(!m)return null;let database=m[2]||'';try{database=decodeURIComponent(database);}catch{}return {host:m[1],database};}
const redactUri=uri=>uri.replace(/(\/\/[^:@\/?#]+:)[^@\/?#]*@/,'$1••••••@');
const testLabel=t=>!t?'Not tested':t.status==='testing'?'Testing connection…':t.status==='ok'?'Connection verified':'Connection failed';
const testDot=t=>`<span class="test-dot ${t?.status||'none'}"></span>${testLabel(t)}`;
function testStatus(t){
 if(!t||t.status==='testing')return `<span class="test-result">${testLabel(t)}</span>`;
 return `<span class="test-result ${t.status}">${ico(t.status==='ok'?'check':'fail')}${testLabel(t)}</span>${t.message?`<span class="test-message">${esc(t.message)}</span>`:''}<span class="test-time">Last tested: ${date(t.at)}</span>`;
}
const settingsFooter=(start='',saveLabel='Save',isNew=false)=>`<div class="panel-foot"><div class="actions">${start}</div><div class="actions"><span class="muted" id="dirty-label">${dirty?'Unsaved changes':isNew?'':'All changes saved'}</span><button class="btn" data-action="cancel-settings">Cancel</button><button class="btn primary" data-action="save-settings">${saveLabel}</button></div></div>`;
const settingsRow=(href,icon,name,detail,value)=>`<a class="settings-link" href="${href}"><span class="settings-link-icon">${ico(icon)}</span><span class="settings-link-text"><strong>${name}</strong><small>${detail}</small></span><span class="settings-link-value">${value}</span>${ico('arrow')}</a>`;
function settingsPage(){
 if(settingsSection==='destinations')return settingsItem?destinationPage():destinationsPage();
 if(settingsSection==='checkpoints')return checkpointsPage();
 const count=state.settings.destinations.length,on=checkpointOn(),row=(id,icon,value,status)=>settingsRow(`#settings/${id}`,icon,SETTINGS_SECTIONS[id][0],SETTINGS_SECTIONS[id][1],`<strong>${value}</strong><small>${status}</small>`);
 return `${title('Settings','Workspace configuration for extractions.')}${viewer()}<section class="panel settings-list">${row('destinations','database',`${count} destination${count===1?'':'s'}`,`Default: ${esc(destinationName())}`)}${row('checkpoints','clock',on?'Enabled':'Disabled',on?'Incremental extraction available':'Full extraction only')}</section>`;
}
function destinationsPage(){
 const [heading,description]=SETTINGS_SECTIONS.destinations;
 const rows=state.settings.destinations.map(d=>settingsRow(`#settings/destinations/${esc(d.id)}`,'database',`${esc(d.name)}${d.id===state.settings.defaultDestination?'<span class="badge default">Default</span>':''}`,`MongoDB · ${esc(mongoTarget(d.uri)?.database||'No database')}`,`<small>${testDot(d.test)}</small>${d.test?`<small>${date(d.test.at)}</small>`:''}`)).join('');
 return `${title(heading,description,`<button class="btn primary" data-action="new-destination" ${disabled()}>${ico('plus')} Add destination</button>`)}${viewer()}<div class="help-box">Every connection and schedule writes new extractions to the default destination.</div><section class="panel settings-list">${rows}</section>`;
}
function destinationPage(){
 const isNew=settingsItem==='new',saved=isNew?null:destinationById(settingsItem),description=SETTINGS_SECTIONS.destinations[1];
 const back='<a class="btn" href="#settings/destinations">Back to data destinations</a>';
 if(!isNew&&!saved)return `${title('Data destinations',description)}<section class="panel">${empty('Destination not found','It may have been deleted. Choose another destination from the list.',back)}</section>`;
 if(isNew&&!canEdit())return `${title('Add data destination',description)}${viewer()}<section class="panel">${empty('Only admins can add destinations','Ask an admin to add the destination you need.',back)}</section>`;
 const isDefault=!isNew&&saved.id===state.settings.defaultDestination;
 const heading=isNew?'Add data destination':esc(saved.name);
 const updated=isNew?'':`<span class="muted settings-updated">Last updated ${date(saved.updatedAt)} by ${esc(saved.updatedBy)}</span>`;
 if(!canEdit())return `${title(heading,description)}${viewer()}<section class="panel settings-panel settings-form"><div class="panel-head"><div><h2>Destination details <span class="view-only-badge">View only</span></h2><p>Managed by an admin.</p></div>${updated}</div><div class="panel-body"><dl class="read-only-values"><div><dt>Destination name</dt><dd><span>${esc(saved.name)}</span></dd></div><div><dt>Database type</dt><dd><span>MongoDB</span></dd></div><div><dt>Connection string</dt><dd><span>${esc(redactUri(saved.uri))}</span></dd></div><div><dt>Target database</dt><dd><span>${esc(mongoTarget(saved.uri)?.database||'—')}</span></dd></div><div><dt>Connection test</dt><dd><span>${testLabel(saved.test)}${saved.test?` · ${date(saved.test.at)}`:''}</span></dd></div><div><dt>Default destination</dt><dd><span>${isDefault?'Yes. New extractions write here.':'No'}</span></dd></div></dl></div></section>`;
 if(!settingsDraft)settingsDraft=isNew?{id:'',name:'',uri:'',test:null,makeDefault:false}:{id:saved.id,name:saved.name,uri:saved.uri,test:saved.test?{...saved.test}:null,makeDefault:isDefault};
 const d=settingsDraft,testing=d.test?.status==='testing';
 const defaultField=`<label class="check-field"><input type="checkbox" id="settings-default" data-setting="makeDefault" ${d.makeDefault?'checked':''} ${isDefault?'disabled':''}><span><strong>Use as the default destination</strong><small>${isDefault?'New extractions write here. To change this, make another destination the default.':'Every connection and schedule will write new extractions here.'}</small></span></label>`;
 return `${title(heading,description)}<section class="panel settings-panel settings-form"><div class="panel-head"><div><h2>Destination details</h2></div>${updated}</div><div class="panel-body"><div class="field"><label for="settings-name">Destination name</label><input id="settings-name" value="${esc(d.name)}" data-setting="name" maxlength="60" autocomplete="off" placeholder="For example, Reporting database"></div><div class="field"><span class="field-label">Database type</span><p class="field-value">MongoDB</p></div><div class="field"><label for="settings-uri">Connection string</label><div class="secret-input"><input id="settings-uri" type="password" value="${esc(d.uri)}" data-setting="uri" autocomplete="off" spellcheck="false" placeholder="mongodb://user:password@host:27017/database"><button type="button" class="text-button" data-action="toggle-secret" aria-controls="settings-uri" aria-pressed="false">Show</button></div></div><div class="field"><span class="field-label">Target database</span><p class="field-value" id="settings-target-db">${esc(mongoTarget(d.uri)?.database||'—')}</p><small>Read from the connection string.</small></div><div class="connection-test"><button type="button" class="btn" id="settings-test" data-action="test-destination" ${testing?'disabled':''}>${testing?'Testing…':'Test connection'}</button><div class="test-status" id="settings-test-status" role="status">${testStatus(d.test)}</div></div>${defaultField}<p class="error" id="settings-error" role="alert"></p></div>${settingsFooter(isNew||isDefault?'':'<button class="btn danger" data-action="delete-destination">Delete destination</button>',isNew?'Add destination':'Save',isNew)}</section>`;
}
function checkpointsPage(){
 const on=checkpointOn(),[heading,description]=SETTINGS_SECTIONS.checkpoints;
 if(!canEdit())return `${title(heading,description)}${viewer()}<section class="panel settings-panel settings-form"><div class="panel-head"><div><h2>Incremental extraction <span class="view-only-badge">View only</span></h2><p>Managed by an admin.</p></div></div><div class="panel-body"><dl class="read-only-values"><div><dt>Checkpoints</dt><dd><span>${on?'Enabled':'Disabled'}</span></dd></div><div><dt>Incremental extraction</dt><dd><span>${on?'Available':'Unavailable. Run a full extraction.'}</span></dd></div></dl></div></section>`;
 if(!settingsDraft)settingsDraft={checkpoint:on};
 const option=(value,label,help)=>`<label class="choice-option"><input type="radio" name="settings-checkpoint" id="settings-checkpoint-${value}" value="${value}" data-setting="checkpoint" ${(settingsDraft.checkpoint?'on':'off')===value?'checked':''}><span><strong>${label}</strong><small>${help}</small></span></label>`;
 return `${title(heading,description)}<section class="panel settings-panel settings-form"><div class="panel-head"><div><h2>Incremental extraction</h2><p>Applies to every connection and schedule.</p></div></div><div class="panel-body"><fieldset class="choice-options"><legend>Checkpoints</legend>${option('on','Enabled','Each extraction saves a checkpoint, so incremental extractions fetch only records changed since the last one.')}${option('off','Disabled','Incremental extraction is unavailable. Run a full extraction each time.')}</fieldset></div>${settingsFooter()}</section>`;
}
function validateDestination(d){
 const name=d.name.trim();
 if(!name)throw Error('Enter a destination name.');
 if(state.settings.destinations.some(x=>x.id!==d.id&&x.name.trim().toLowerCase()===name.toLowerCase()))throw Error(`Another destination is already named ${name}. Use a different name.`);
 const target=mongoTarget(d.uri);
 if(!target)throw Error('Enter a MongoDB connection string that starts with mongodb:// or mongodb+srv://.');
 if(!target.database)throw Error('Add the database name to the end of the connection string, for example …:27017/edap_analytics.');
 if(!/^[A-Za-z0-9_-]+$/.test(target.database))throw Error('Use letters, numbers, hyphens, or underscores in the database name.');
}
function settingsError(message){if($('#settings-error'))$('#settings-error').textContent=message;}
// Refresh the parts of the destination form that follow the connection string, without redrawing the inputs being typed in.
function destinationStatus(){
 const d=settingsDraft;if(!d||!('uri' in d))return;
 const testing=d.test?.status==='testing',button=$('#settings-test');
 if($('#settings-target-db'))$('#settings-target-db').textContent=mongoTarget(d.uri)?.database||'—';
 if(button){button.disabled=testing;button.textContent=testing?'Testing…':'Test connection';}
 if($('#settings-test-status'))$('#settings-test-status').innerHTML=testStatus(d.test);
}
// Stand-in for the server-side check: EDAP's servers can't reach a database on localhost; any other host answers.
function testDestination(){
 if(!admin()||!settingsDraft)return;
 const d=settingsDraft;
 try{validateDestination(d);}catch(e){settingsError(e.message);return;}
 settingsError('');d.test={status:'testing',uri:d.uri.trim()};destinationStatus();
 setTimeout(()=>destinationTested(d),900);
}
function destinationTested(d){
 if(d.test?.status!=='testing')return; // The connection string changed while the test ran.
 const local=/^(localhost|127\.|\[::1\])/i.test(mongoTarget(d.test.uri).host);
 d.test={status:local?'failed':'ok',uri:d.test.uri,at:Date.now(),...(local?{message:"EDAP can't reach a database on localhost. Use a host name its servers can reach."}:{})};
 // A test of a saved string is a fact about that destination, so it is kept even without Save.
 const saved=destinationById(d.id);
 if(saved&&d.test.uri===saved.uri){saved.test=d.test;save();}
 if(settingsDraft===d)destinationStatus();
}
function saveSettings(){
 if(!admin()||!settingsDraft)return;
 const d=settingsDraft;
 if(settingsSection==='checkpoints'){state.settings.checkpoint={enabled:!!d.checkpoint};save();dirty=false;settingsDraft=null;render();toast(d.checkpoint?'Checkpoints turned on. Incremental extraction is available.':'Checkpoints turned off. Extractions run in full.');return;}
 try{validateDestination(d);}catch(e){settingsError(e.message);toast(e.message);return;}
 const saved=destinationById(d.id),name=d.name.trim(),uri=d.uri.trim();
 const test=d.test&&d.test.status!=='testing'&&d.test.uri===uri?d.test:saved&&uri===saved.uri?saved.test:null;
 const next={id:saved?.id||'d-'+crypto.randomUUID().slice(0,8),name,type:'mongo',uri,test,updatedAt:Date.now(),updatedBy:'jordan@aziro.com'};
 if(saved)Object.assign(saved,next);else state.settings.destinations.push(next);
 // The default destination is where every connection and schedule writes, so a new default replaces it on each of them.
 const madeDefault=d.makeDefault&&state.settings.defaultDestination!==next.id;
 if(madeDefault){state.settings.defaultDestination=next.id;state.connections.forEach(c=>{c.destination=next.id;});state.schedules.forEach(s=>{s.destination=next.id;});}
 save();dirty=false;settingsDraft=null;
 toast(`${saved?'Destination saved.':`${name} added.`}${madeDefault?` New extractions will write to ${name}.`:''}${test?.status==='ok'?'':' Test the connection to check it.'}`);
 if(saved)render();else location.hash='#settings/destinations';
}
function deleteDestination(){
 const d=destinationById(settingsItem);
 if(!admin()||!d||d.id===state.settings.defaultDestination)return;
 openModal('delete-destination',`Delete ${esc(d.name)}?`,'Extraction history is kept.',`<p>New extractions can no longer write to this destination. Records already in ${esc(mongoTarget(d.uri)?.database||'its database')} stay there.</p>`,`<button class="btn" data-action="close-modal">Keep destination</button><button class="btn danger" data-action="confirm-delete-destination">Delete destination</button>`);
}
function render(){nav();$('#main').innerHTML=({overview,catalog:catalogPage,connections:connectionsPage,detail,runs:runsPage,schedules:schedulesPage,settings:settingsPage}[view]||overview)();if(view==='catalog')catalogResults();if(view==='connections')connectionsResults();if(view==='runs')runsResults();if(view==='detail')renderMappings();}
function openModal(type,title,subtitle,body,footer=''){modalType=type;$('#modal').classList.remove('disconnect-modal');$('#modal').innerHTML=`<div class="modal-head"><div><div class="eyebrow">EDAP WORKSPACE</div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="close" data-action="close-modal" aria-label="Close dialog">×</button></div><div class="modal-content">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!$('#modal').open)$('#modal').showModal();}
function openDisconnectModal(id){
 const c=connection(id);if(!c)return;
 modalType='disconnect';const modal=$('#modal');
 modal.classList.add('disconnect-modal');
 modal.innerHTML=`<button class="close disconnect-close" data-action="close-modal" aria-label="Close dialog">×</button><div class="disconnect-split"><aside class="disconnect-identity"><div class="eyebrow">YOUR CONNECTION</div><img src="assets/logos/${esc(c.app)}.svg" alt="${esc(meta(c.app).name)}"><h3>${esc(c.name)}</h3><p>${esc(c.account)}</p><span class="disconnect-kind">Personal connection</span></aside><div class="disconnect-decision"><h2 id="modal-title">Ready to disconnect?</h2><p class="disconnect-lead">This connection will be removed from EDAP.</p><ul><li>Associated schedules will be removed.</li><li>Running extractions will be cancelled.</li></ul><div class="disconnect-note">Your previous run history will remain available.</div><div class="disconnect-actions"><button class="btn" data-action="close-modal" autofocus>Keep connection</button><button class="btn disconnect-confirm" data-action="confirm-disconnect" data-id="${esc(id)}">Disconnect</button></div></div></div>`;
 if(!modal.open)modal.showModal();modal.querySelector('[autofocus]').focus();
}
function closeModal(){ $('#modal').close();modalType='';modalRun='';wizard=null; }
function connectWizard(appId,reconnectId=''){if(!admin())return;const a=meta(appId),old=connection(reconnectId);wizard={app:appId,step:1,reconnectId,name:old?.name||`${a.name} · My account`,endpoint:old?.endpoint||(a.category==='Databases'?'db.example.internal':a.id==='jira'?'https://your-team.atlassian.net':''),account:old?.account||'jordan@aziro.com',auth:old?.auth||a.auth[0],authorized:false,objects:old?.objects||[...a.objects],destination:old?.destination||state.settings.defaultDestination};drawWizard();}
function drawWizard(){const w=wizard,a=meta(w.app);let body=`<div class="steps">${['Authenticate','Configure','Review'].map((name,i)=>`<span class="step ${w.step===i+1?'current':''}"><b>${w.step>i+1?'✓':i+1}</b>${name}</span>`).join('')}</div>`;if(w.step===1){body+=`<div class="field"><label for="auth-method">Authentication method</label><select id="auth-method">${a.auth.map(v=>`<option ${w.auth===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="auth-account">${a.category==='Databases'?'Username':'Account email'}</label><input id="auth-account" value="${esc(w.account)}" placeholder="jordan@aziro.com"></div>${w.auth==='OAuth'?`<div class="oauth">${appIcon(a,true)}<h3>Authorize your ${a.name} account</h3><p>Continue with your account to configure this connection.</p><button class="btn primary" data-action="authorize">${ico(w.authorized?'check':'shield')} ${w.authorized?'Account selected':'Continue with account'}</button></div>`:`${w.auth==='Client credentials'?`<div class="field"><label for="auth-client">Client ID</label><input id="auth-client" placeholder="Client ID" autocomplete="off"></div>`:''}<div class="field"><label for="auth-secret">${w.auth==='Database credentials'?'Password':w.auth==='Service account'?'Service account JSON':w.auth==='Client credentials'?'Client secret':'API token'}</label><input id="auth-secret" type="password" placeholder="Enter credential" autocomplete="off"></div>`}`;}
if(w.step===2)body+=`<div class="fields-two"><div class="field"><label for="setup-name">Connection name</label><input id="setup-name" maxlength="80" value="${esc(w.name)}"></div><div class="field"><label for="setup-endpoint">${a.category==='Databases'?'Database host':'Application URL'}</label><input id="setup-endpoint" value="${esc(w.endpoint)}" placeholder="${a.category==='Databases'?'db.example.internal':'https://your-workspace.example.com'}"></div></div><div class="section-label">DATA SCOPE · ALL OBJECTS SELECTED BY DEFAULT</div>${a.objects.map(o=>`<div class="object-row"><input type="checkbox" id="setup-${o}" data-setup-object="${o}" ${w.objects.includes(o)?'checked':''}><label for="setup-${o}">${o}</label></div>`).join('')}<div style="margin-top:20px">${destinationSummary(w.destination)}</div>`;
if(w.step===3)body+=`<div class="help-box"><strong>${ico('check')} Ready to connect</strong><p>Review your personal connection. You can adjust field mappings after saving.</p></div><ul class="review-list">${[['Application',a.name],['Connection',w.name],['Account',w.account],['Authentication',w.auth],['Source',w.endpoint],['Objects',w.objects.join(', ')],['Destination',destinationName(w.destination)]].map(([k,v])=>`<li><span>${k}</span><strong>${esc(v)}</strong></li>`).join('')}</ul>`;
body+='<p class="error" id="wizard-error" role="alert"></p>';openModal('wizard',w.reconnectId?'Reconnect '+a.name:'Connect '+a.name,'Your account. Your data.',body,`<button class="btn" data-action="${w.step===1?'close-modal':'wizard-back'}">${w.step===1?'Cancel':'Back'}</button><button class="btn primary" data-action="wizard-next">${w.step===3?'Save connection':'Continue'} ${ico('arrow')}</button>`);}
function wizardNext(){if(!admin())return;const w=wizard;const error=m=>$('#wizard-error').textContent=m;if(w.step===1){w.account=$('#auth-account').value.trim();if(!w.account)return error('Enter an account name to continue.');if(meta(w.app).category!=='Databases'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(w.account))return error('Enter a valid account email.');if(w.auth==='OAuth'&&!w.authorized)return error('Complete account authorization before continuing.');if(w.auth!=='OAuth'&&!$('#auth-secret').value.trim())return error('Enter a credential to continue.');if(w.auth==='Client credentials'&&!$('#auth-client').value.trim())return error('Enter a client ID.');w.authorized=true;}
if(w.step===2){w.name=$('#setup-name').value.trim();w.endpoint=$('#setup-endpoint').value.trim();w.objects=[...document.querySelectorAll('[data-setup-object]:checked')].map(e=>e.dataset.setupObject);if(!w.name||!w.endpoint)return error('Enter a connection name and application URL or database host.');if(meta(w.app).category!=='Databases'){try{const u=new URL(w.endpoint);if(!['https:','http:'].includes(u.protocol)||u.username||u.password)throw Error();}catch{return error('Enter an HTTP or HTTPS application URL without credentials.');}}if(!w.objects.length)return error('Select at least one object.');}
if(w.step<3){w.step++;drawWizard();return;}let c=connection(w.reconnectId);if(c){Object.assign(c,{name:w.name,endpoint:w.endpoint,account:w.account,auth:w.auth,status:'connected',objects:w.objects,destination:w.destination});}else{c={id:'c-'+crypto.randomUUID(),app:w.app,name:w.name,endpoint:w.endpoint,account:w.account,auth:w.auth,status:'connected',objects:w.objects,destination:w.destination,mappings:mappingsFor(w.app),filter:'',limit:500,created:Date.now()};state.connections.push(c);}save();closeModal();draft=null;jsonDraft=null;dirty=false;tab='connection';location.hash='connection/'+c.id;route();toast('Connection saved.');}
function markDirty(){dirty=true;if($('#dirty-label'))$('#dirty-label').textContent='Unsaved changes';}
function validateDraft(c){if(!c.name.trim())throw Error('Enter a connection name.');if(!c.endpoint.trim())throw Error('Enter an application URL or database host.');if(meta(c.app).category!=='Databases'){try{const u=new URL(c.endpoint);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw Error();}catch{throw Error('Use an HTTP or HTTPS URL without credentials.');}}if(!c.objects.length)throw Error('Select at least one object.');if(!Number.isInteger(+c.limit)||+c.limit<1||+c.limit>1000000)throw Error('Record limit must be a whole number between 1 and 1,000,000.');for(const o of c.objects){const values=Object.values(c.mappings[o]||{});if(!values.length)throw Error(`Configure at least one field for ${o}.`);if(values.some(v=>typeof v!=='string'||!v.trim()||v.length>80)||new Set(values).size!==values.length)throw Error(`Output fields for ${o} must be non-empty, unique names of up to 80 characters.`);}}
function saveConfig(){if(!admin())return;try{validateDraft(draft);draft.limit=Number(draft.limit);Object.assign(connection(detailId),structuredClone(draft));save();dirty=false;jsonDraft=null;render();toast('Configuration saved. New extractions will use these settings.');}catch(e){toast(e.message);}}
function saveJSON(){if(!admin())return;try{let json;try{json=JSON.parse($('#json-editor').value);}catch{throw Error('Invalid JSON. Check double quotes, commas, and matching brackets, then try again.');}if(!json||typeof json!=='object'||Array.isArray(json))throw Error('Enter a configuration object with connector, objects, options, and destination.');if(json.connector!==draft.app)throw Error('Connector type cannot be changed.');if(!json.objects||typeof json.objects!=='object'||Array.isArray(json.objects))throw Error('Objects must be a named object map.');if(Object.keys(json).some(k=>!['connector','objects','options','destination'].includes(k)))throw Error('Only connector, objects, options, and destination are supported.');const supported=meta(draft.app).objects;if(Object.keys(json.objects).some(o=>!supported.includes(o)))throw Error('Configuration contains an unsupported object.');const next=structuredClone(draft);next.objects=[];next.mappings={};for(const o of supported){const obj=json.objects[o];if(!obj){next.mappings[o]=draft.mappings[o];continue;}if(typeof obj.enabled!=='boolean'||!obj.fields||typeof obj.fields!=='object'||Array.isArray(obj.fields))throw Error(`Provide enabled (boolean) and fields (object) for ${o}.`);if(Object.keys(obj).some(k=>!['enabled','fields'].includes(k)))throw Error(`Unknown setting in ${o}.`);if(Object.keys(obj.fields).some(k=>!k.trim()||k.length>80||['__proto__','prototype','constructor'].includes(k)))throw Error(`Invalid source field in ${o}.`);if(obj.enabled)next.objects.push(o);next.mappings[o]=obj.fields;}if(!json.options||typeof json.options.filter!=='string'||typeof json.options.maxRecords!=='number')throw Error('Options require a text filter and numeric maxRecords.');if(Object.keys(json.options).some(k=>!['filter','maxRecords'].includes(k)))throw Error('Unknown option. Use filter and maxRecords.');next.filter=json.options.filter;next.limit=json.options.maxRecords;if(json.destination!==draft.destination)throw Error('Destination cannot be changed here. An admin changes it on the Settings page.');validateDraft(next);draft=next;saveConfig();}catch(e){$('#json-error').textContent=e.message;}}
function runDialog(id){const c=connection(id);if(!c)return toast('Choose an existing connection.');openModal('run','Run extraction',c.name,runFields(c,'modal-run'),`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="start-modal-run" data-id="${c.id}">${ico('play')} Run extraction</button>`);}
// Runs when an extraction mode is picked: for Incremental, say whether the destination has a checkpoint configured.
function modeNote(prefix,value){const note=$('#'+prefix+'-mode-note');if(!note)return;const err=$('#'+prefix+'-error');if(err&&/^Checkpoint is not configured/.test(err.textContent))err.textContent='';const db=esc(destinationName(note.dataset.destination));note.hidden=value!=='incremental';note.className=checkpointOn()?'mode-note ok':'mode-note';note.innerHTML=checkpointOn()?`<strong>Checkpoint is configured for ${db}.</strong> Only records changed since the last successful run will be extracted.`:`<strong>Checkpoint is not configured for ${db}.</strong> Run a full extraction first. ${canEdit()?'<button type="button" class="text-button" data-action="open-settings" data-section="checkpoints">Turn on checkpoints in Settings</button>':'An admin can turn checkpoints on in Settings.'}`;}
function readRunOptions(c,prefix='run'){
 const chosen=$('#'+prefix+'-object').value;
 if(!chosen)throw Error('Select an object to extract.');
 const objects=chosen==='all'?c.objects:[chosen];
 if(objects.some(o=>!c.objects.includes(o)))throw Error('Choose only objects included in the saved configuration.');
 const incremental=$(`input[name="${prefix}-mode"]:checked`)?.value==='incremental';
 if(incremental&&!checkpointOn())throw Error(`Checkpoint is not configured for ${destinationName(c.destination)}. Run a full extraction first.`);
 const options={objects:[...new Set(objects)],mode:incremental?'incremental':'full',destination:c.destination,fail:$('#'+prefix+'-outcome').value==='failure'};
 if(c.app==='jira'){
  const projectKey=$('#'+prefix+'-project').value;
  if(!JIRA_PROJECTS.some(([k])=>k===projectKey))throw Error('Select a project key for this extraction.');
  options.projectKey=projectKey;options.jql=$('#'+prefix+'-jql').value.trim();
 }
 return options;
}
function beginRun(id,options){const c=connection(id);if(!c){toast('Connection no longer exists.');return null;}const requested=options.objects??c.objects;
 if(!Array.isArray(requested)||!requested.length||requested.some(o=>!c.objects.includes(o))){
  const message='The selected objects are no longer available in this connection. Start a new extraction using the current configuration.';
  if($('#retry-error'))$('#retry-error').textContent=message;
  toast(message);return null;
 }
 const objects=[...new Set(requested)];
 if(state.runs.some(r=>r.connection===id&&r.status==='running')){toast('An extraction is already running for this connection.');return null;}const run={id:'run-'+crypto.randomUUID().slice(0,8),connection:id,app:c.app,name:c.name,mode:options.mode==='incremental'&&checkpointOn()?'incremental':'full',destination:destinationById(options.destination)?options.destination:c.destination,objects,status:c.status==='attention'?'failed':'running',count:0,time:Date.now(),progress:0,target:Math.min(c.limit*objects.length,options.mode==='incremental'&&checkpointOn()?126:420),fail:!!options.fail,source:options.source||'Manual',mappings:structuredClone(c.mappings)};if(options.projectKey){run.projectKey=options.projectKey;run.jql=options.jql||'';}if(c.status==='attention')run.error='Authorization expired. Reconnect this account before retrying.';state.runs.unshift(run);save();render();return run;}
// Extractions run in the background. Starting one closes any dialog and falls back to the runs list, which carries the status.
function runStarted(run){if(!run)return;if(modalType)closeModal();toast(run.status==='failed'?`Extraction could not start. ${run.error}`:'Extraction started in the background. Track its status on Extraction runs.');if(dirty)return;if(location.hash==='#runs')route();else location.hash='#runs';}
function startRun(id,prefix='run'){const c=connection(id);try{const options=readRunOptions(c,prefix);runStarted(beginRun(id,options));}catch(e){$('#'+prefix+'-error').textContent=e.message;}}
function runDetails(id){const r=state.runs.find(x=>x.id===id);if(!r)return;modalRun=id;const canRetry=['failed','cancelled'].includes(r.status)&&!!connection(r.connection);const note=r.status==='running'?'<p class="run-note" role="status">This extraction is running in the background. You can close this window and keep working. Its status updates on Extraction runs, and the output can be previewed or downloaded once it completes.</p>':r.status==='completed'?'<p class="run-note success">Completed. Preview or download up to 5 output records.</p>':`<p class="run-note danger">${esc(r.error||(r.status==='cancelled'?'Cancelled by user. No output committed.':'Extraction failed.'))}</p>`;openModal('run-detail','Extraction details',r.id,`<div class="actions" style="justify-content:space-between;margin-bottom:20px"><h3>${esc(r.name)}</h3>${badge(r.status)}</div><ul class="review-list"><li><span>Mode</span><strong>${r.mode==='full'?'Full extraction':'Incremental extraction'}</strong></li><li><span>Destination</span><strong>${esc(destinationName(r.destination))}</strong></li><li><span>Objects</span><strong>${esc((r.objects||[]).join(', ')||'All objects')}</strong></li>${r.projectKey?`<li><span>Project key</span><strong>${esc(r.projectKey)}</strong></li><li><span>JQL filter</span><strong>${esc(r.jql||'None')}</strong></li>`:''}<li><span>Started by</span><strong>${esc(r.source||'Manual')}</strong></li><li><span>Started · IST</span><strong>${date(r.time)}</strong></li>${r.finished||r.status==='running'?`<li><span>Finished · IST</span><strong>${r.finished?date(r.finished):'In progress'}</strong></li>`:''}<li><span>Records extracted</span><strong>${r.status==='completed'?fmt(r.count):'—'}</strong></li></ul>${note}<p id="retry-error" class="error" role="alert"></p>`,`<button class="btn" data-action="close-modal">Close</button><div class="actions">${r.status==='running'?`<button class="btn danger" data-action="cancel-run" data-id="${r.id}">Cancel run</button>`:''}${canRetry?`<button class="btn primary" data-action="retry-run" data-id="${r.id}">Retry extraction</button>`:''}${r.status==='completed'?`<button class="btn" data-action="preview-output" data-id="${r.id}">Preview output</button><button class="btn primary" data-action="download" data-id="${r.id}">${ico('download')} Sample JSONL</button>`:''}</div>`);modalRun=id;}
function sampleRows(r){return Array.from({length:Math.min(5,r.count)},(_,i)=>{const object=r.objects?.[i%r.objects.length]||meta(r.app).objects[0];const fields=r.mappings?.[object]||mappingsFor(r.app)[object];const data={};Object.entries(fields||{}).forEach(([src,dest])=>{data[dest]=src==='id'?`record-${i+1}`:src==='size'?1024*(i+1):/date|updated/i.test(src)?new Date(r.time).toISOString():src==='webUrl'?'https://example.com/record':`Sample ${src} ${i+1}`;});return {sample:true,connector:r.app,object,data};});}
function download(r){const blob=new Blob([sampleRows(r).map(row=>JSON.stringify(row)).join('\n')+'\n'],{type:'application/x-ndjson'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`edap-${r.app}-${r.id}-sample.jsonl`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Downloaded up to 5 output records.');}
const intervalFor=f=>({hourly:3600000,daily:86400000,weekly:604800000})[f];
function scheduleDialog(id=''){if(!admin())return;if(!state.connections.length)return toast('Connect an application before creating a schedule.');const s=state.schedules.find(s=>s.id===id);openModal('schedule',s?'Edit schedule':'Create schedule','Recurring extractions for your personal connections.',`<div class="field"><label for="schedule-connection">Connection</label><select id="schedule-connection">${state.connections.map(c=>`<option value="${c.id}" ${s?.connection===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="fields-two"><div class="field"><label for="schedule-frequency">Frequency</label><select id="schedule-frequency">${[['hourly','Every hour'],['daily','Every day'],['weekly','Every week']].map(([v,l])=>`<option value="${v}" ${s?.frequency===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label for="schedule-mode">Mode</label><select id="schedule-mode"><option value="full" ${!checkpointOn()||s?.mode==='full'?'selected':''}>Full extraction</option><option value="incremental" ${checkpointOn()?(!s||s.mode==='incremental'?'selected':''):'disabled'}>Incremental extraction${checkpointOn()?'':' (needs checkpoints)'}</option></select>${checkpointOn()?'':'<small>Checkpoints are off in Settings, so schedules run a full extraction.</small>'}</div></div><div class="help-box">The first run is one interval after saving. Missed intervals produce one catch-up run.</div>${destinationSummary(s?.destination)}`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-schedule" data-id="${id}">Save schedule</button>`);}
const runStatuses=['Completed','Running','Failed','Cancelled'];
const runStatusFromSlug=slug=>runStatuses.find(v=>v.toLowerCase()===slug)||'All statuses';
function route(){const hash=location.hash.slice(1)||'overview';const parts=hash.split('/');view=parts[0]==='connection'?'detail':['overview','connections','catalog','runs','schedules','settings'].includes(parts[0])?parts[0]:'overview';detailId=parts[1]||'';settingsSection=view==='settings'&&SETTINGS_SECTIONS[parts[1]]?parts[1]:'';settingsItem=settingsSection==='destinations'?parts[2]||'':'';if(view==='detail')tab=canEdit()?'connection':'extraction';draft=null;jsonDraft=null;settingsDraft=null;dirty=false;filterText='';category='All categories';statusFilter=view==='runs'?runStatusFromSlug(parts[1]):'All statuses';runApp='all';render();window.scrollTo(0,0);}
function confirmDiscard(next){if(!dirty){next();return;}openModal('discard','Discard unsaved changes?','Your saved configuration will be kept.','<p>Changes you made since the last save will be discarded.</p>','<button class="btn" data-action="close-modal">Keep editing</button><button class="btn danger" id="discard-confirm">Discard changes</button>');$('#discard-confirm').onclick=()=>{dirty=false;draft=null;jsonDraft=null;settingsDraft=null;closeModal();next();};}
document.addEventListener('click',event=>{const link=event.target.closest('a[href]');if(link&&dirty&&!link.getAttribute('href').startsWith('#connection/'+detailId)){event.preventDefault();confirmDiscard(()=>{location.href=link.href;});return;}const btn=event.target.closest('[data-action]');if(!btn||btn.disabled)return;const id=btn.dataset.id,action=btn.dataset.action;switch(action){case 'save-settings':saveSettings();break;case 'cancel-settings':confirmDiscard(()=>{location.hash=settingsSection==='destinations'?'#settings/destinations':'#settings';});break;case 'new-destination':if(admin())location.hash='#settings/destinations/new';break;case 'delete-destination':deleteDestination();break;case 'confirm-delete-destination':{const d=destinationById(settingsItem);if(!admin()||!d||d.id===state.settings.defaultDestination)break;state.settings.destinations=state.settings.destinations.filter(x=>x!==d);save();dirty=false;settingsDraft=null;closeModal();location.hash='#settings/destinations';toast(`${d.name} deleted.`);break;}case 'test-destination':testDestination();break;case 'toggle-secret':{const input=$('#'+btn.getAttribute('aria-controls')),show=input.type==='password';input.type=show?'text':'password';btn.textContent=show?'Hide':'Show';btn.setAttribute('aria-pressed',String(show));break;}case 'open-settings':if($('#modal').open)closeModal();location.hash='#settings'+(btn.dataset.section?'/'+btn.dataset.section:'');break;case 'activity-app':activityApp=id;render();break;
case 'filter-category':category=id;document.querySelectorAll('.category-tag').forEach(tag=>tag.setAttribute('aria-pressed',String(tag.dataset.id===category)));catalogResults();break;
case 'clear-connection-filters':filterText='';statusFilter='All statuses';render();$('#connection-search').focus();break;
case 'close-modal':closeModal();break;
case 'copy-connection-value':copyConnectionValue(id,btn.dataset.field);break;
case 'connect':connectWizard(id);break;
case 'reauth':connectWizard(connection(id).app,id);break;
case 'authorize':wizard.account=$('#auth-account').value.trim();wizard.authorized=true;drawWizard();break;
case 'wizard-next':wizardNext();break;
case 'wizard-back':if(wizard.step===2){wizard.name=$('#setup-name').value;wizard.endpoint=$('#setup-endpoint').value;wizard.objects=[...document.querySelectorAll('[data-setup-object]:checked')].map(e=>e.dataset.setupObject);}wizard.step--;drawWizard();break;
case 'tab':if(tab==='json'&&dirty){confirmDiscard(()=>{tab=id;render();});}else{tab=id;render();}break;
case 'save-config':saveConfig();break;
case 'save-json':saveJSON();break;
case 'reload-config':confirmDiscard(()=>{draft=null;jsonDraft=null;render();toast('Saved configuration restored.');});break;
case 'all-objects':if(admin()){draft.objects=[...meta(draft.app).objects];markDirty();render();}break;
case 'test':toast(connection(id).status==='connected'?'Connection configuration is ready.':'Connection test failed · authorization expired. Reconnect this account.');break;
case 'disconnect':if(admin())openDisconnectModal(id);break;
case 'confirm-disconnect':if(admin()){state.runs.filter(r=>r.connection===id&&r.status==='running').forEach(r=>{r.status='cancelled';r.error='Connection disconnected. No output committed.';});state.connections=state.connections.filter(c=>c.id!==id);state.schedules=state.schedules.filter(s=>s.connection!==id);save();dirty=false;closeModal();location.hash='connections';toast('Connection disconnected.');}break;
case 'run':runDialog(id);break;
case 'choose-run':if(!state.connections.length){toast('Connect an application first.');break;}openModal('choose-run','Choose a connection','Start a new extraction.',`<div class="field"><label for="choose-connection">Connection</label><select id="choose-connection">${state.connections.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div>`,'<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="chosen-run">Continue</button>');break;
case 'chosen-run':runDialog($('#choose-connection').value);break;
case 'start-modal-run':startRun(id,'modal-run');break;
case 'start-detail-run':startRun(id);break;
case 'run-detail':runDetails(id);break;
case 'cancel-run':{const r=state.runs.find(r=>r.id===id);if(r?.status==='running'){r.status='cancelled';r.error='Cancelled by user. No output committed.';r.finished=Date.now();save();render();runDetails(id);}break;}
case 'retry-run':{const r=state.runs.find(r=>r.id===id);const next=beginRun(r.connection,{mode:r.mode,destination:r.destination,objects:r.objects,projectKey:r.projectKey,jql:r.jql,source:'Retry'});runStarted(next);break;}
case 'download':download(state.runs.find(r=>r.id===id));break;
case 'preview-output':{const r=state.runs.find(r=>r.id===id);openModal('output','Sample output',meta(r.app).name+' · Up to 5 records',`<pre class="run-log">${esc(sampleRows(r).map(row=>JSON.stringify(row,null,2)).join('\n'))}</pre>`,`<button class="btn" data-action="run-detail" data-id="${id}">Back to run</button><button class="btn primary" data-action="download" data-id="${id}">${ico('download')} Download sample</button>`);break;}
case 'new-schedule':scheduleDialog();break;
case 'edit-schedule':scheduleDialog(id);break;
case 'save-schedule':if(admin()){const existing=state.schedules.find(s=>s.id===id);const frequency=$('#schedule-frequency').value;const data={connection:$('#schedule-connection').value,frequency,mode:$('#schedule-mode').value,destination:state.settings.defaultDestination,next:Date.now()+intervalFor(frequency)};if(existing)Object.assign(existing,data);else state.schedules.push({id:'s-'+crypto.randomUUID(),active:true,...data});save();closeModal();render();toast('Schedule saved.');}break;
case 'toggle-schedule':if(admin()){const s=state.schedules.find(s=>s.id===id);s.active=!s.active;if(s.active)s.next=Date.now()+intervalFor(s.frequency);save();render();toast(s.active?'Schedule resumed.':'Schedule paused.');}break;
case 'delete-schedule':if(admin())openModal('delete-schedule','Delete this schedule?','','<p>The connection and previous run history will remain available.</p>',`<button class="btn" data-action="close-modal">Keep schedule</button><button class="btn danger" data-action="confirm-delete-schedule" data-id="${id}">Delete schedule</button>`);break;
case 'confirm-delete-schedule':if(admin()){state.schedules=state.schedules.filter(s=>s.id!==id);save();closeModal();render();toast('Schedule deleted.');}break;
case 'schedule-run':{const s=state.schedules.find(s=>s.id===id);const r=beginRun(s.connection,{mode:s.mode,destination:s.destination,source:'Schedule'});runStarted(r);break;}
}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='catalog-search'){filterText=el.value;catalogResults();}if(el.id==='connection-search'){filterText=el.value;connectionsResults();}if(el.id==='run-search'){filterText=el.value;runsResults();}if(el.dataset.draft&&canEdit()){draft[el.dataset.draft]=el.value;markDirty();}if(el.dataset.mapping&&canEdit()){draft.mappings[$('#mapping-object').value][el.dataset.mapping]=el.value;markDirty();}if(el.id==='json-editor'&&canEdit()){jsonDraft=el.value;markDirty();}if(el.dataset.setting&&canEdit()&&settingsDraft){const setting=el.dataset.setting;if(setting==='checkpoint')settingsDraft.checkpoint=el.value==='on';else if(setting==='makeDefault')settingsDraft.makeDefault=el.checked;else{settingsDraft[setting]=el.value;if(setting==='uri'){settingsDraft.test=null;settingsError('');destinationStatus();}}markDirty();}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='activity-range'){activityRange=el.value;render();}if(el.id==='activity-connector'){activityApp=el.value;render();}if(el.id==='connection-status'){statusFilter=el.value;connectionsResults();}if(el.id==='run-status'){statusFilter=el.value;runsResults();history.replaceState(history.state,'',statusFilter==='All statuses'?'#runs':'#runs/'+statusFilter.toLowerCase());activeRouteHash=location.hash;}if(el.id==='run-connector'){runApp=el.value;runsResults();}if(el.type==='radio'&&/-mode$/.test(el.name||''))modeNote(el.name.slice(0,-5),el.value);if(el.id==='mapping-object')renderMappings();if(el.dataset.object&&canEdit()){draft.objects=meta(draft.app).objects.filter(o=>o===el.dataset.object?el.checked:draft.objects.includes(o));markDirty();render();}if(el.id==='auth-method'){wizard.account=$('#auth-account').value;wizard.auth=el.value;wizard.authorized=false;drawWizard();}if(el.id==='role'){const role=el.value;$('#role').value=state.role;confirmDiscard(()=>{state.role=role;if(view==='detail')tab=canEdit()?'connection':'extraction';save();render();toast('Role changed to '+role+'.');});}});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key==='s'&&(view==='detail'||view==='settings')){event.preventDefault();if(view==='settings')saveSettings();else if(tab==='json')saveJSON();else saveConfig();}});
$('#modal').addEventListener('cancel',event=>{event.preventDefault();closeModal();});
// Index same-document history so Back/Forward can be reversed without losing a draft.
let historyPosition=history.state?.edapPosition??0;
let activeRouteHash=location.hash;
let pendingHistoryNavigation=null;
history.replaceState({...history.state,edapPosition:historyPosition},'',location.href);
function handleHistoryNavigation(){
 const targetHash=location.hash;
 const position=history.state?.edapPosition;
 if(pendingHistoryNavigation){
  const pending=pendingHistoryNavigation;
  pendingHistoryNavigation=null;
  confirmDiscard(()=>history.go(pending.delta));
  return;
 }
 if(dirty&&targetHash!==activeRouteHash){
  if(Number.isInteger(position)&&position!==historyPosition){
   const delta=position-historyPosition;
   pendingHistoryNavigation={delta};
   history.go(-delta);
  }else{
   // An entry created before history tracking began: preserve the draft and URL.
   historyPosition++;
   history.pushState({edapPosition:historyPosition},'',activeRouteHash||location.pathname);
   confirmDiscard(()=>{location.hash=targetHash;});
  }
  return;
 }
 if(Number.isInteger(position))historyPosition=position;
 else{historyPosition++;history.replaceState({...history.state,edapPosition:historyPosition},'',location.href);}
 if(dirty&&targetHash===activeRouteHash)return;
 activeRouteHash=targetHash;
 route();
}
window.addEventListener('hashchange',handleHistoryNavigation);
window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
setInterval(()=>{let changed=false,refresh=false;const settled=[];for(const r of state.runs){if(r.status!=='running')continue;r.progress=Math.min(100,r.progress+13);r.count=Math.round(r.target*r.progress/100);if(r.fail&&r.progress>=65){r.status='failed';r.error='Source timeout. Retry the extraction to recover.';}else if(r.progress===100)r.status='completed';if(r.status!=='running'){r.finished=Date.now();settled.push(r);}changed=true;}for(const s of state.schedules){if(s.active&&s.next<=Date.now()){beginRun(s.connection,{mode:s.mode,destination:s.destination,source:'Scheduled'});s.next=Date.now()+intervalFor(s.frequency);changed=refresh=true;}}if(changed)save();
 // Runs work in the background, so the UI only changes when a status does: no live progress.
 if(settled.length||refresh){if(['overview','connections','runs','schedules'].includes(view)||(view==='detail'&&tab==='history')){if(view==='runs')runsResults();else if(view==='connections')connectionsResults();else render();}if(modalType==='run-detail'&&settled.some(r=>r.id===modalRun)){const focused=document.activeElement?.dataset?.action;runDetails(modalRun);if(focused)$('#modal').querySelector(`[data-action="${focused}"]`)?.focus();}const mine=settled.filter(r=>r.source!=='Scheduled');if(mine.length===1)toast(mine[0].status==='completed'?`${mine[0].name} extraction completed. Preview or download the output on Extraction runs.`:`${mine[0].name} extraction failed. Open its details on Extraction runs to retry.`);else if(mine.length>1)toast(`${mine.length} extractions finished. See their status on Extraction runs.`);}},1100);
route();save();if(!storageAvailable)toast('Browser storage is unavailable. Changes will last for this session only.');

// Native disclosure supports keyboard activation; dismiss with Escape or outside click.
function chartTip(col,active){
 const host=col.closest('.overview-activity'),tip=host?.querySelector('.chart-tip');if(!tip)return;
 tip.textContent='';
 const head=document.createElement('div');head.className='chart-tip-head';head.textContent=col.dataset.label+' · '+fmt(col.dataset.count)+' records · '+plural(Number(col.dataset.runs),'run');tip.append(head);
 col.querySelectorAll('.chart-seg').forEach(seg=>{const row=document.createElement('div');row.className='chart-tip-row'+(seg===active?' active':'');const key=document.createElement('span');key.className='chart-tip-key';key.style.setProperty('--seg',seg.style.getPropertyValue('--seg'));const value=document.createElement('strong');value.textContent=fmt(seg.dataset.count);const name=document.createElement('span');name.textContent=seg.dataset.name+' · '+plural(Number(seg.dataset.runs),'run');row.append(key,value,name);tip.append(row);});
 const hr=host.getBoundingClientRect(),sr=col.querySelector('.chart-stack').getBoundingClientRect();
 tip.hidden=false;tip.style.left=(sr.left+sr.width/2-hr.left)+'px';tip.style.top=(sr.top-hr.top)+'px';
}
const hideChartTip=()=>document.querySelectorAll('.chart-tip').forEach(t=>{t.hidden=true;});
document.addEventListener('pointerover',event=>{const col=event.target.closest?.('.chart-col.has-data');if(col)chartTip(col,event.target.closest('.chart-seg'));});
document.addEventListener('pointerout',event=>{const col=event.target.closest?.('.chart-col.has-data');if(col&&!col.contains(event.relatedTarget))hideChartTip();});
document.addEventListener('focusin',event=>{const seg=event.target.closest?.('.chart-seg');if(seg)chartTip(seg.closest('.chart-col'),seg);});
document.addEventListener('focusout',event=>{if(event.target.closest?.('.chart-seg'))hideChartTip();});
document.addEventListener('click',event=>{const menu=$('#user-menu');if(menu?.open&&!menu.contains(event.target))menu.open=false;});
document.addEventListener('keydown',event=>{const menu=$('#user-menu');if(event.key==='Escape'&&menu?.open){menu.open=false;menu.querySelector('summary').focus();}});

// Keep embedded actions independent from the connection row shortcut.
document.addEventListener('click',event=>{
 const row=event.target.closest('[data-connection-href]');
 if(!row||event.target.closest('a,button,input,select,textarea,label')||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;
 if(window.getSelection()?.toString())return;
 location.hash=row.dataset.connectionHref;
});
document.addEventListener('keydown',event=>{
 const row=event.target.closest('[data-connection-href]');
 if(row&&event.target===row&&(event.key==='Enter'||event.key===' ')){
  event.preventDefault();location.hash=row.dataset.connectionHref;
 }
});
